function drawBuilding(b,p,tw,th){
 const type=b.type,level=b.level||1,selectedBuilding=selected===b.id;ctx.save();ctx.translate(p.x,p.y+th*.26);
 const palette={hq:['#c0aa82','#8d765b','#62513f','#d1b484'],grow:['#8caa76','#638153','#405a39','#b5ce83'],greenhouse:['#aec5a2','#789678','#526d58','#d4e7c1'],lab:['#a9aaa0','#797c73','#53574f','#d5a878'],warehouse:['#b79a70','#8d704d','#624e38','#d2b37d'],security:['#9aaead','#718484','#4e6264','#bed1c9']}[type]||['#a8b09c','#788373','#4c5648','#c7cfad'];
 const w=tw*.78,d=th*.88,wall=tw*.48,baseY=wall*.48;
 // A deep ground shadow and a raised concrete foundation make the footprint readable.
 ctx.fillStyle='#14201970';ctx.beginPath();ctx.ellipse(3,baseY+5,w*.66,d*.78,0,0,Math.PI*2);ctx.fill();
 ctx.fillStyle='#777b62';ctx.beginPath();ctx.moveTo(-w*.54,baseY);ctx.lineTo(0,baseY+d*.42);ctx.lineTo(w*.54,baseY);ctx.lineTo(0,baseY-d*.42);ctx.closePath();ctx.fill();
 // Two lit exterior walls, with visible corners, windows and a proper entrance.
 ctx.fillStyle=palette[1];ctx.beginPath();ctx.moveTo(-w*.5,-wall*.28);ctx.lineTo(0,-wall*.28+d*.4);ctx.lineTo(0,baseY+d*.4);ctx.lineTo(-w*.5,baseY);ctx.closePath();ctx.fill();
 ctx.fillStyle=palette[2];ctx.beginPath();ctx.moveTo(0,-wall*.28+d*.4);ctx.lineTo(w*.5,-wall*.28);ctx.lineTo(w*.5,baseY);ctx.lineTo(0,baseY+d*.4);ctx.closePath();ctx.fill();
 // Flat roof deck with a bright parapet lip reads as a complete building from above.
 ctx.fillStyle=palette[0];ctx.beginPath();ctx.moveTo(-w*.5,-wall*.3);ctx.lineTo(0,-wall*.3+d*.4);ctx.lineTo(w*.5,-wall*.3);ctx.lineTo(0,-wall*.3-d*.4);ctx.closePath();ctx.fill();
 ctx.strokeStyle=palette[3];ctx.lineWidth=Math.max(1.3,tw*.035);ctx.beginPath();ctx.moveTo(-w*.5,-wall*.3);ctx.lineTo(0,-wall*.3+d*.4);ctx.lineTo(w*.5,-wall*.3);ctx.stroke();
 // Rooftop details by facility type.
 if(type==='greenhouse'){ctx.fillStyle='#bddbb4b8';ctx.beginPath();ctx.moveTo(-w*.34,-wall*.32);ctx.lineTo(0,-wall*.3+d*.25);ctx.lineTo(w*.34,-wall*.32);ctx.lineTo(0,-wall*.32-d*.25);ctx.closePath();ctx.fill();ctx.strokeStyle='#e2f0d0';ctx.lineWidth=1;for(let i=-1;i<=1;i++){ctx.beginPath();ctx.moveTo(i*w*.18,-wall*.3);ctx.lineTo(i*w*.18*.6,-wall*.3+d*.4);ctx.stroke()}}
 else if(type==='security'){ctx.fillStyle='#556b69';ctx.fillRect(-w*.12,-wall*.48,w*.24,wall*.18);ctx.fillStyle='#df7463';ctx.beginPath();ctx.arc(w*.17,-wall*.45,Math.max(2,tw*.035),0,Math.PI*2);ctx.fill()}
 else {ctx.fillStyle=type==='grow'?'#557548':type==='hq'?'#76644d':type==='lab'?'#60635c':'#766248';ctx.fillRect(-w*.18,-wall*.48,w*.36,wall*.16);ctx.fillStyle='#d4d2b5';ctx.fillRect(-w*.12,-wall*.45,w*.08,wall*.05);ctx.fillRect(w*.04,-wall*.45,w*.08,wall*.05)}
 // Windows are set into both visible walls; the door anchors the front facade.
 const winW=Math.max(3,w*.12),winH=Math.max(3,wall*.13);ctx.fillStyle=type==='greenhouse'?'#d9efce':'#c6d6bb';
 for(let i=0;i<2;i++){let wx=-w*.34+i*w*.22;ctx.fillRect(wx,-wall*.04,winW,winH);ctx.fillStyle='#526958';ctx.fillRect(wx+winW*.45,-wall*.04,1,winH);ctx.fillStyle=type==='greenhouse'?'#d9efce':'#c6d6bb'}
 ctx.fillStyle='#342d25';ctx.fillRect(-w*.07,wall*.09,w*.14,wall*.32);ctx.fillStyle='#e6c77d';ctx.beginPath();ctx.arc(w*.035,wall*.25,Math.max(1,tw*.012),0,Math.PI*2);ctx.fill();
 if(type==='warehouse'){ctx.strokeStyle='#d0b17d';ctx.lineWidth=1.3;ctx.strokeRect(w*.12,wall*.03,w*.2,wall*.29);ctx.beginPath();ctx.moveTo(w*.22,wall*.03);ctx.lineTo(w*.22,wall*.32);ctx.stroke()}
 if(type==='grow'){ctx.fillStyle='#b6da81';for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(-w*.37+i*w*.13,-wall*.38,Math.max(2,tw*.025),Math.max(3,tw*.055),-.4,0,Math.PI*2);ctx.fill()}}
 if(selectedBuilding){ctx.strokeStyle='#d5f092';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(0,baseY+4,w*.68,d*.78,0,0,Math.PI*2);ctx.stroke()}
 ctx.font=`${Math.max(8,Math.min(10,tw*.16))}px "DM Mono"`;ctx.textAlign='center';const label=type==='hq'?'HQ':defs[type].name.replace('Underground ','').replace(' House','').replace('Glasshouse','Glass').replace('Mixing Lab','Lab').replace('Watchtower','Watch');ctx.fillStyle='#172019e8';ctx.fillRect(-32,baseY+7,64,14);ctx.fillStyle='#f3f5e9';ctx.fillText(label,0,baseY+17);
 if(b.upgradeAt||b.paused){ctx.fillStyle=b.paused?'#e37462':'#edc569';ctx.font='bold 12px sans-serif';ctx.fillText(b.paused?'Ⅱ':'↑',w*.42,-wall*.5)}ctx.restore()}

