.toast{bottom:72px}.modal{padding:22px 18px}.modal h2{font-size:19px}}

/* Building interiors: a distinct, navigable screen reached by selecting a structure. */
.interior-screen{display:none;min-height:0;flex:1;overflow:auto;padding:2px 3px 14px;scrollbar-width:thin;scrollbar-color:#405344 transparent}
.game-area.inside-building .map-toolbar,.game-area.inside-building .map-frame,.game-area.inside-building .map-footer{display:none}
.game-area.inside-building .interior-screen{display:block}
.interior-topline{display:flex;align-items:center;gap:14px;height:40px;border-bottom:1px solid #29382f;margin-bottom:17px}
.back-to-map{background:#202d25;border:1px solid #384b3d;color:#d4e5c4;border-radius:7px;padding:8px 11px;font-size:11px;font-weight:700}
